SELECT a.chembl_id AS assay_chembl_id, td.target_type, td.tax_id, cs.canonical_smiles, md.chembl_id AS molecule_chembl_id, act.standard_type, act.pchembl_value FROM target_dictionary td JOIN assays a ON a.tid = td.tid JOIN activities act ON act.assay_id = a.assay_id JOIN molecule_dictionary md ON md.molregno = act.molregno JOIN compound_structures cs ON cs.molregno = md.molregno WHERE td.chembl_id = 'CHEMBL1628462' AND act.standard_type = 'IC50' AND act.standard_relation = '=' AND act.pchembl_value IS NOT NULL ORDER BY md.chembl_id, a.chembl_id LIMIT 1000
